\begin{Theorem}\label{thm:mthetamorph1}
Let $v=(v_j)_{0 \leq j \leq r} \in \mathbb{N}^{r+1}$ be any vector satisfying $v_i=n_i$ for all $i \in I$. Suppose that $\mathfrak{M}_{\theta_I}(1,v)$ is non-empty. For the vector $(1,\vprime)\in \mathcal{V}(n_I)$ from Corollary~{\rm \ref{cor:non-empty}}, choose a vector~$\widetilde{\vprime}$ as in Proposition~{\rm \ref{prop:surjvar}}. Then
there is a commutative diagram
\begin{equation}\label{eqn:keyrevisited}
\begin{tikzcd}
 & \mathfrak{M}_{\widetilde{\theta}}\big(1, \widetilde{\vprime}\big) \arrow[dl, "\pi_I", swap ] \arrow[dr, "\tau_I" ]& \\
 \mathfrak{M}_{\theta_I}(1, \vprime) \arrow[rr, "\iota_I" ] & & \mathcal{M}_{\PiQ_I} (1,n_I)
\end{tikzcd}
\end{equation}
 of schemes over $\C$, where $\iota_I$ is an isomorphism of the underlying reduced schemes. Thus, $\mathcal{M}_{\PiQ_I}(1,n_I)$ is non-empty, irreducible, and its
underlying reduced scheme is normal and has symplectic singularities.
\end{Theorem}

\begin{lemma}
    For $(Z,\calP)$ as above and $t\in (0,1]$, we have
    \begin{align}
        \calP(1-t)
        &= H_{\theta_t}[-1]\cap H^{\theta_t}\\
        &= \left\{
            h\in H \;\middle\vert\;
            \begin{array}{l}
                \theta_t(x)=0\ ,\text{ and }\theta_t(s)\geq 0\\[2pt]
                \text{for all sub-objects }s\hookrightarrow x
            \end{array}
        \right\}\ .
    \end{align}
\end{lemma}

\begin{theorem}\label{thTaylorExpansions}
	Let $f$ be an admissible polynomial. Then the expansions
	\begin{equation}\label{eqTaylorExpansions}
		S_{22}^f(z) = 2z_1z_2 + \bar{o}(z^2),\;\;
		S_{12}^f(z) = -z_2^2 + \bar{o}(z^2),\;\;
		S_{11}^f(z) = 1 + \bar{o}(z^2)
	\end{equation}
	hold.
\end{theorem}

\begin{lemma}\label{lemThetaConvergence}
	Assume that $\Omega$ is a quasi-reduced Riemann matrix and let $\{c_n\}_{n \in \mathbb N}$ be any sequence of positive real numbers that converges to $+\infty$. Consider any sequence $\{f_n\}_{n \in \NN}$, where $f_n \in R_2^{c_n \Omega}$. Then the following statements hold.
	\begin{enumerate}[label=(\roman*)]
		\item\label{thetaconvergencei} The sequence $\{f_n\}$ converges uniformly on compact subsets in $\CC^2$ if only if the sequence $p_n$ converges, where $p_n$ is the order $2$ Taylor expansion of $f_n$ at zero (i.e. $f_n(z) = p_n(z) + \bar{o}(z^2)$.
		\item\label{thetaconvergenceii} If the sequence $\{f_n\}$ converges uniformly on compact subsets in $\CC^2$, and $f$ denotes the limit of this sequence, then \[f \in \Span\{1, \sin^2(\pi z_1), \sin^2(\pi z_2),\sin^2(\pi(z_1 - z_2))\}.\]
	\end{enumerate}
\end{lemma}
